    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0x8D1F944B0501C6A5ULL + 0xE2342F7D91258E71ULL);
