            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x950787961EB0B9E3ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterF) ^ 0x1B14834DD13BEF85ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 24U)) & S_SALT1];
