            aOrbiterB = RotL64((aOrbiterB * 0xBE5E565176C31097ULL), 53U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0xBBCE1F3958B44334ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 5U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0x5673D1DF250B8F01ULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x83F7E70D09D14339ULL), 39U);
