            aOrbiterH = RotL64((aOrbiterH * 0x8C682F76E08B279BULL), 43U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0x71B97B02534895D2ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 17U)) & S_SALT1];
