            //
            aOrbiterH = (aWandererJ + RotL64(aCross, 53U)) + 0xA6A2212D6B6362BBULL;
            aOrbiterI = ((aWandererH + RotL64(aPrevious, 34U)) + 0x33A4C8CE91AB569AULL) + aTwistOrbiterAssignSaltE[((aIndex + 12U)) & S_SALT1];
            aOrbiterF = (aWandererC + RotL64(aIngress, 19U)) + 0xF4F9D4AA96957CDCULL;
            aOrbiterK = ((aWandererA + RotL64(aScatter, 23U)) + RotL64(aCarry, 3U)) + 0x54C0AAF111D5BDB0ULL;
            aOrbiterB = ((aWandererD + RotL64(aPrevious, 3U)) + 0x741B6D859EDA2709ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterA = (aWandererI + RotL64(aScatter, 39U)) + 0x9AFE9CB6371BF865ULL;
            aOrbiterJ = ((aWandererK + RotL64(aIngress, 46U)) + RotL64(aCarry, 39U)) + 0x2DA11F7E87F03605ULL;
            aOrbiterD = ((aWandererE + RotL64(aCross, 11U)) + RotL64(aCarry, 11U)) + 0x2BBB8FCA13D5E5F4ULL;
            aOrbiterE = (aWandererF + RotL64(aIngress, 57U)) + 0xC816E19ADC8B7323ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x1792E635CDC54ACDULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x347E3632D29C7183ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x28DB71160C4DC4BDULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x2E9643BE621D2F18ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterF) ^ 0x8F37589EA63AAB6BULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x9A2ADAA5E3B8AA81ULL), 23U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x9D3A783A8747E34EULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x2E27E6D12C4C122CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xEF56BEFA94A4DB35ULL), 41U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0xB85C98907B9DF2DEULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0x43EB26D32862EB15ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 24U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x9D96999604EF98E3ULL), 57U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0xAC7ADE6231251593ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 5U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0xA6DEFB0E5525C44EULL;
