            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x5508B9EFDC586AAAULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x6547C195C1053A90ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x5B026D83724D20B3ULL), 35U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x543A8D6D71A9532FULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0xEBA881CB38EBB34BULL;
            aOrbiterD = RotL64((aOrbiterD * 0xF52D961FA28504B9ULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x328644A1395F7F6CULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x1DD5CA6A65AA5EADULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA93674525AFA074BULL), 53U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0xE33508A7B52AC6DEULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xE81099A41B8119F2ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x7C6ED1049D711D45ULL), 29U);
