            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterH, 51U));
            aIngress = aIngress + (RotL64(aOrbiterJ, 23U) ^ aOrbiterE);
            aIngress = aIngress + RotL64(aOrbiterF, 19U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ ((RotL64(aCross, 58U) + RotL64(aOrbiterI, 34U)) + aOrbiterJ);
            aWandererF = aWandererF + ((RotL64(aPrevious, 47U) + aOrbiterI) + RotL64(aOrbiterB, 23U));
