            aOrbiterJ = ((aWandererD + RotL64(aPrevious, 47U)) + 0xB7D78C28D72368CFULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 13U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aScatter, 18U)) + RotL64(aCarry, 5U)) + 0x058C199BADCA603FULL;
            aOrbiterC = ((aWandererI + RotL64(aIngress, 53U)) + 0x0B480E66FB164FE8ULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 17U)) & S_SALT1];
