            aOrbiterF = (aWandererG + RotL64(aPrevious, 5U)) + 0xE90C20962A2639C6ULL;
            aOrbiterH = (aWandererH + RotL64(aScatter, 30U)) + 0xCFB473B033F966FBULL;
            aOrbiterG = (aWandererB + RotL64(aIngress, 35U)) + 0x6420560785B870C8ULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x8DDB8E94A8FBF8DBULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xB7C6299B85848473ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x85E52C6B10575BCDULL), 53U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0xF96D8455D37CF913ULL) + aKeyRotateAOrbiterUpdateSaltA[((aIndex + 21U)) & S_SALT1];
