            aOrbiterB = (aOrbiterB + aOrbiterE) + 0xB6B6BBA572024C09ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x43E87BCA7B47A2A7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x377BDDFB574DD4ABULL), 39U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0x07A1C4E7DF8EA4C5ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 17U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x40F811BB30664301ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x5D7A3E67ACADF1C9ULL), 37U);
