            aWandererJ = aWandererJ + ((RotL64(aPrevious, 35U) + aOrbiterG) + RotL64(aOrbiterK, 39U));
            aWandererF = aWandererF ^ ((RotL64(aIngress, 56U) + RotL64(aOrbiterJ, 34U)) + aOrbiterA);
            aWandererA = aWandererA + ((RotL64(aScatter, 13U) + aOrbiterG) + RotL64(aOrbiterA, 53U));
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 23U) + aOrbiterI) + RotL64(aOrbiterD, 3U));
            aWandererG = aWandererG + (((RotL64(aIngress, 27U) + RotL64(aOrbiterC, 57U)) + aOrbiterB) + RotL64(aCarry, 35U));
            aWandererC = aWandererC ^ ((RotL64(aScatter, 19U) + RotL64(aOrbiterD, 41U)) + aOrbiterA);
