            aOrbiterJ = ((aWandererD + RotL64(aScatter, 53U)) + 0x15A7823E7E9AB017ULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterC = (((aWandererI + RotL64(aIngress, 29U)) + RotL64(aCarry, 51U)) + 0xE65B0782485833C9ULL) + aKeyRotateAOrbiterAssignSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterG = ((aWandererK + RotL64(aPrevious, 5U)) + RotL64(aCarry, 35U)) + 0xA39F6AC1A9695A97ULL;
