            //
            aScatter = (RotL64(aIngress, 27U) + RotL64(aCross, 5U)) + (RotL64(aPrevious, 54U) ^ RotL64(aCarry, 41U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterB = (aWandererD + RotL64(aIngress, 23U)) + 0x5A2BB53913D89538ULL;
            aOrbiterC = ((aWandererG + RotL64(aScatter, 43U)) + RotL64(aCarry, 5U)) + 0x73B783AD6DABD8D0ULL;
            aOrbiterF = ((aWandererF + RotL64(aPrevious, 53U)) + RotL64(aCarry, 29U)) + 0x1C84BCD69C42251BULL;
            aOrbiterG = (((aWandererC + RotL64(aCross, 3U)) + RotL64(aCarry, 43U)) + 0x9A2557726A36E0E5ULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterJ = (aWandererA + RotL64(aScatter, 37U)) + 0x9B6D49D4EF676B72ULL;
            aOrbiterH = ((aWandererK + RotL64(aIngress, 60U)) + 0x9985E7255FA7F313ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterI = (aWandererI + RotL64(aPrevious, 13U)) + 0x47B65BBA9A749F64ULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0xF1B5FDE7864304B5ULL) + aKeyRotateAOrbiterUpdateSaltD[((aIndex + 21U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x7CB78B75B3192545ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1D7CDBC71B109299ULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x1553E3C83BF77425ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x812064870ADA5233ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x2348BE415B575215ULL), 29U);
