            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x06076308A2CDC44AULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xAFB72AB03ADBC507ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x2DEAD491443AE451ULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x4808D64F5CBF4360ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xF29D614291EFDAE5ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xD224383DBF40D9BBULL), 5U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0xC26F7159AE54C3E2ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 9U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0xD88AE16D2190AB82ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x183B121A306B09F3ULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xFA328BC7DA4EB062ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x5F3B7C835C2D41C4ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x924A0FC4ED2099EDULL), 13U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0x167D54F560D4E407ULL) + aKeyRotateAOrbiterUpdateSaltA[((aIndex + 27U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0xC419765F481EA24EULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 29U)) & S_SALT1];
