            //
            aWandererF = aWandererF + ((((RotL64(aIngress, 57U) + RotL64(aOrbiterF, 58U)) + aOrbiterB) + RotL64(aCarry, 37U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 24U)) & S_SALT1]);
            aWandererD = aWandererD ^ (((RotL64(aScatter, 29U) + RotL64(aOrbiterF, 51U)) + aOrbiterG) + aKeyRotateAWandererUpdateSaltE[(((31U - aIndex) + 18U)) & S_SALT1]);
            aWandererG = aWandererG + (((RotL64(aCross, 51U) + RotL64(aOrbiterB, 23U)) + aOrbiterC) + RotL64(aCarry, 21U));
