            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterH = ((aWandererE + RotL64(aScatter, 5U)) + RotL64(aCarry, 51U)) + 0x973337730B373033ULL;
            aOrbiterK = (aWandererJ + RotL64(aPrevious, 46U)) + 0xE23907C9115A3D54ULL;
            aOrbiterI = (((aWandererK + RotL64(aCross, 57U)) + RotL64(aCarry, 35U)) + 0xD23999BCA3F7C384ULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterA = ((aWandererG + RotL64(aIngress, 29U)) + RotL64(aCarry, 13U)) + 0x8CA8F4C90DD0888EULL;
            aOrbiterG = (aWandererI + RotL64(aPrevious, 13U)) + 0x8BC63F30A72B0D64ULL;
            aOrbiterJ = ((aWandererF + RotL64(aScatter, 39U)) + 0xFC489308EB637AFEULL) + aKeyRotateAOrbiterAssignSaltD[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterE = (aWandererA + RotL64(aIngress, 23U)) + 0x2E537D0A7824F38AULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x5BEC96C8EB4FEADFULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0xCB65187759E4FE46ULL;
