            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x9EDDF358397824FDULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0xE4F121D5F7E2F102ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xCA4F1747DCC3F81FULL), 29U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterH) + 0xBEF5675F8C607B4DULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 9U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0xAB6847D760BFA20BULL;
            aOrbiterK = RotL64((aOrbiterK * 0xA2F2175B1DA444ABULL), 35U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x8343892959B6E5ADULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterK) ^ 0xC93F6E39E7B05E90ULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x72733284ED576F51ULL), 51U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x948A21B0AEBD560DULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterG) ^ 0xD60F8941C50592E9ULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 5U)) & S_SALT1];
