            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0x526FAC06189D15A8ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0xE2C0F8BB4F017429ULL;
