            aWandererE = aWandererE + ((((RotL64(aScatter, 13U) + aOrbiterE) + RotL64(aOrbiterH, 21U)) + RotL64(aCarry, 11U)) + aKeyRotateAWandererUpdateSaltA[((aIndex + 17U)) & S_SALT1]);
