            //
            aScatter = (RotL64(aIngress, 34U) + RotL64(aCarry, 3U)) + (RotL64(aPrevious, 21U) ^ RotL64(aCross, 51U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterH = ((aWandererA + RotL64(aCross, 41U)) + RotL64(aCarry, 27U)) + 0x53159859309BEC15ULL;
            aOrbiterA = ((aWandererH + RotL64(aPrevious, 3U)) + RotL64(aCarry, 53U)) + 0x81B88A93418F1CC9ULL;
            aOrbiterJ = ((aWandererI + RotL64(aScatter, 21U)) + 0x6DCDE4231E427097ULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterG = (aWandererJ + RotL64(aIngress, 35U)) + 0x5630A40484878E48ULL;
            aOrbiterC = ((aWandererD + RotL64(aScatter, 51U)) + RotL64(aCarry, 41U)) + 0x379F762A1BB78861ULL;
            aOrbiterI = (aWandererE + RotL64(aCross, 60U)) + 0xE9D71CEE629165CDULL;
            aOrbiterK = ((aWandererK + RotL64(aIngress, 13U)) + 0xB22EF11760AA66DBULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 29U)) & S_SALT1];
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0xA9EF39E866117DEEULL) + aKeyRotateAOrbiterUpdateSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterH) ^ 0xBF9F16CB28EB3E75ULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x531DA287ECAE4A61ULL), 53U);
