            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x1AA8793A11F394CCULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x1CC55483E38C6E5EULL;
            aOrbiterI = RotL64((aOrbiterI * 0x6428EA7EB82C5299ULL), 47U);
