            aWandererK = aWandererK + (((RotL64(aCross, 11U) + RotL64(aOrbiterG, 37U)) + aOrbiterK) + aKeyRotateAWandererUpdateSaltF[((aIndex + 22U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aScatter, 30U) + RotL64(aOrbiterA, 57U)) + aOrbiterH) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 26U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aIngress, 51U) + RotL64(aOrbiterG, 29U)) + aOrbiterJ) + RotL64(aCarry, 19U));
            aWandererE = aWandererE ^ ((RotL64(aScatter, 3U) + RotL64(aOrbiterC, 3U)) + aOrbiterG);
