            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0xC2B19BCE1406922EULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0xB05B608746C0B44CULL) ^ aKeyRotateBOrbiterUpdateSaltD[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x729C5E0928272459ULL), 11U);
