            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x5892BD581F906DCFULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterB) ^ 0x39B5E74424FE84D6ULL) ^ aKeyRotateBOrbiterUpdateSaltE[((aIndex + 7U)) & S_SALT1];
